import queue


def accepted(cap: int, xs: list[int]) -> int:
    """Put each element of xs into a bounded queue.Queue of capacity cap
    without blocking, in order. Return the number of puts accepted before
    the queue was first full; stop at that point (remaining elements are
    not attempted). Note queue.Queue treats cap <= 0 as unbounded, so a
    cap of 0 or less accepts every element."""
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_all_fit() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_exact_capacity() -> None:
    assert accepted(3, [1, 2, 3]) == 3


def test_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3, 4, 5]) == 2


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_capacity_one() -> None:
    assert accepted(1, [7, 8, 9]) == 1


def test_duplicates_are_counted() -> None:
    assert accepted(3, [5, 5, 5, 5]) == 3


def test_nonpositive_capacity_is_unbounded() -> None:
    assert accepted(0, [1, 2, 3, 4]) == 4
    assert accepted(-1, [1, 2]) == 2

